function firstMissingPositive(nums) {
  const n = nums.length;

  let i = 0;
  while (i < n) {
    const target = nums[i] - 1;          // value v belongs at index v-1
    if (nums[i] > 0 && nums[i] <= n && nums[i] !== nums[target]) {
      [nums[i], nums[target]] = [nums[target], nums[i]];
    } else {
      i++;
    }
  }

  for (let j = 0; j < n; j++) {
    if (nums[j] !== j + 1) return j + 1;
  }
  return n + 1;
}
